<style>
  body {
    font-family: "Times New Roman", Times, serif;
    font-size: 14px;
    line-height: 1.35;
    color: #000;
    margin: 0;
    padding: 20px 30px;
  }
  .page {
    display: flex;
    gap: 30px;
    max-width: 1500px;
    margin: 0 auto;
  }
  .col {
    flex: 1;
    min-width: 0;
  }
  figure {
    margin: 0 0 6px 0;
  }
  figcaption {
    font-size: 12.5px;
    text-align: left;
    margin-top: 6px;
  }
  figcaption b {
    font-weight: bold;
  }
  .chart-box {
    border: 1px solid #000;
    width: 100%;
    height: 340px;
    box-sizing: border-box;
    position: relative;
    padding: 10px;
    background: #fff;
  }
  .chart-title-top {
    text-align: center;
    font-size: 13px;
    margin-bottom: 4px;
  }
  .chart-inner {
    position: relative;
    height: calc(100% - 20px);
    border-left: 1.5px solid #000;
    border-bottom: 1.5px solid #000;
    margin-left: 40px;
    margin-bottom: 25px;
  }
  .yaxis-label {
    position: absolute;
    left: -35px;
    top: 40%;
    transform: rotate(-90deg) translateX(-50%);
    font-size: 13px;
    white-space: nowrap;
  }
  .xaxis-label {
    text-align: center;
    font-size: 13px;
    margin-top: 4px;
    margin-left: 40px;
  }
  .legend-box {
    position: absolute;
    border: 1px solid #000;
    background: #fff;
    font-size: 11px;
    padding: 6px 10px;
    line-height: 1.6;
  }
  .legend-line {
    display: block;
    white-space: nowrap;
  }
  .swatch {
    display: inline-block;
    width: 18px;
    border-top-width: 2px;
    margin-right: 5px;
    vertical-align: middle;
  }
  .curve-note {
    position: absolute;
    font-size: 11px;
    color: #333;
  }
  table.datatable {
    border-collapse: collapse;
    width: 100%;
    font-size: 13px;
    margin-top: 4px;
  }
  table.datatable th, table.datatable td {
    border: 1px solid #000;
    padding: 3px 8px;
    text-align: center;
  }
  .table-caption {
    text-align: center;
    margin-top: 14px;
    font-size: 13.5px;
  }
  .table-caption .small-caps {
    font-variant: small-caps;
    font-weight: bold;
  }
  .footnote {
    font-size: 11px;
    margin-top: 3px;
  }
  .placeholder {
    border: 1px solid #333;
    background: #fafafa;
    box-sizing: border-box;
    position: relative;
    font-size: 12px;
    color: #333;
  }
  .fig10a {
    width: 100%;
    height: 300px;
    margin-bottom: 8px;
  }
  .fig10b {
    width: 100%;
    height: 260px;
  }
  .label-tag {
    position: absolute;
    font-size: 12px;
    color: #000;
  }
  .dashedbox {
    position: absolute;
    border: 1.5px dashed #000;
  }
  .grayzone {
    position: absolute;
    background: #ddd;
  }
  .feedline {
    position: absolute;
    background: #333;
  }
  h3 {
    font-size: 15px;
    font-style: italic;
    margin: 18px 0 6px 0;
  }
  p {
    margin: 0 0 10px 0;
    text-align: justify;
  }
  a { color: blue; text-decoration: none; }
</style>
</head>
<body>

