    <div class="table-caption">
      <div><span class="small-caps">TABLE II</span></div>
      <div><span class="small-caps">Statistics of Different Algorithm Results for<br>the Wideband Microstrip Antenna Design</span></div>
    </div>
    <table class="datatable">
      <thead>
        <tr>
          <th>Algorithm</th>
          <th>Worst iter.</th>
          <th>Best iter.</th>
          <th>Mean iter.</th>
          <th>Time*</th>
        </tr>
      </thead>
      <tbody>
        <tr>
          <td>BPSO w/ imp. TF</td>
          <td>&gt;1000</td>
          <td>250</td>
          <td>&gt; 680</td>
          <td>&gt; 17.94 h</td>
        </tr>
        <tr>
          <td>MLAO-AGD</td>
          <td>342</td>
          <td>107</td>
          <td>254</td>
          <td>9.62 h</td>
        </tr>
      </tbody>
    </table>
    <div class="footnote">* The time for the BPSO with an improved TF is estimated using the mean full-wave simulation time used in MLAO-AGD.</div>

  </div>

  <!-- RIGHT COLUMN -->
  <div class="col">

    <!-- Fig 10 -->
    <figure>
      <div class="placeholder fig10a">
        <!-- top plane -->
        <div class="label-tag" style="left:38%; top:2%;">w<sub>1</sub></div>
        <div style="position:absolute; left:0%; top:8%; width:100%; border-top:1px solid #000;"></div>
        <div style="position:absolute; left:0%; top:8%; bottom:20%; border-left:1px solid #000;"></div>
