        <div style="position:absolute; left:25%; top:35%; width:5px; height:5px; background:#000; border-radius:50%;"></div>
        <div style="position:absolute; left:70%; top:35%; width:5px; height:5px; background:#000; border-radius:50%;"></div>

        <div class="label-tag" style="left:44%; bottom:2%; right:2%; text-align:center;">(a)</div>
